def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    p = [props.get(t.get('element')) or {} for t in sites]
    occ = [1.0 if t.get('occupancy') is None else t.get('occupancy') for t in sites]
    n = len(sites)
    field = [0.0 for k in range(n)]
    weight = [0.0 for k in range(n)]
    for bond in s.get('neighbors') or []:
        i, j = bond.get('i'), bond.get('j')
        d = bond.get('distance_A')
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n:
            continue
        a, b = p[i].get('covalent_radius_A'), p[j].get('covalent_radius_A')
        ei, ej = p[i].get('eneg'), p[j].get('eneg')
        if a is None or b is None or ei is None or ej is None:
            continue
        if not all(isfinite(v) for v in [a, b, ei, ej]) or a <= 0 or b <= 0:
            continue
        if d is None or not isfinite(d) or d <= 0 or occ[j] <= 0:
            continue
        x = d / (1.25 * (a + b))
        if x < 2.5:
            w = occ[j] * exp(-(x ** 6))
            field[i] += w * (ej - ei)
            weight[i] += w
    ids = [i for i in range(n) if weight[i] > 0 and isfinite(occ[i]) and occ[i] > 0]
    z = sum(occ[i] for i in ids)
    if z <= 0:
        return nan
    mean = sum(occ[i] * field[i] / weight[i] for i in ids) / z
    var = sum(occ[i] * (field[i] / weight[i] - mean) ** 2 for i in ids) / z
    return float(sqrt(max(0.0, var)))

def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3')
    if v is None or not isfinite(v) or v <= 0:
        return nan
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for site in s.get('sites') or []:
        e = (props.get(site.get('element')) or {}).get('valence_electrons')
        o = site.get('occupancy')
        o = 1.0 if o is None else o
        if e is not None and isfinite(e) and isfinite(o) and o > 0:
            total += o * e
            weight += o
    return float(total / (weight * v)) if weight > 0 else nan

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    matrix = (s.get('lattice') or {}).get('matrix')
    n = len(sites)
    if n == 0 or matrix is None or len(matrix) != 3:
        return nan
    occ = [1.0 if t.get('occupancy') is None else t.get('occupancy') for t in sites]
    near = [inf for k in range(n)]
    bonds = s.get('neighbors') or []
    for bond in bonds:
        i, j = bond.get('i'), bond.get('j')
        d = bond.get('distance_A')
        if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and d > 0 and occ[j] > 0:
            near[i] = min(near[i], d)
    tensors = np.zeros((n, 3, 3))
    weights = np.zeros(n)
    for bond in bonds:
        i, j = bond.get('i'), bond.get('j')
        d = bond.get('distance_A')
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n:
            continue
        if d is None or not isfinite(d) or d <= 0 or d > 1.6 * near[i] or occ[j] <= 0:
            continue
        fi, fj = sites[i].get('frac_coords'), sites[j].get('frac_coords')
        image = bond.get('image')
        if fi is None or fj is None or image is None:
            continue
        vector = [sum((fj[k] + image[k] - fi[k]) * matrix[k][a] for k in range(3)) for a in range(3)]
        norm2 = sum(v * v for v in vector)
        if not isfinite(norm2) or norm2 <= 0:
            continue
        w = occ[j] * exp(-((d / (1.2 * near[i])) ** 6))
        weights[i] += w
        for a in range(3):
            for b in range(3):
                tensors[i, a, b] += w * vector[a] * vector[b] / norm2
    total = 0.0
    z = 0.0
    for i in range(n):
        if weights[i] > 0 and isfinite(occ[i]) and occ[i] > 0:
            q = sum(tensors[i, a, b] ** 2 for a in range(3) for b in range(3)) / weights[i] ** 2
            total += occ[i] * max(0.0, min(1.0, (3.0 * q - 1.0) / 2.0))
            z += occ[i]
    return float(total / z) if z > 0 else nan

def feature(s):
