        fi, fj = sites[i].get('frac_coords'), sites[j].get('frac_coords')
        image = bond.get('image')
        if fi is None or fj is None or image is None:
            continue
        vector = [sum((fj[k] + image[k] - fi[k]) * matrix[k][a] for k in range(3)) for a in range(3)]
        norm = sqrt(sum(v * v for v in vector))
        if not isfinite(norm) or norm <= 0:
            continue
        w = occ[j] * exp(-((d / (1.2 * near[i])) ** 6))
        weights[i] += w
        for a in range(3):
            vectors[i, a] += w * vector[a] / norm
    total = 0.0
    z = 0.0
    for i in range(n):
        if weights[i] > 0 and isfinite(occ[i]) and occ[i] > 0:
            total += occ[i] * sqrt(sum(vectors[i, a] ** 2 for a in range(3))) / weights[i]
            z += occ[i]
    return float(total / z) if z > 0 else nan

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    occ = [1.0 if t.get('occupancy') is None else t.get('occupancy') for t in sites]
    bonds = s.get('neighbors') or []
    near = [inf for k in range(n)]
    for bond in bonds:
        i, j = bond.get('i'), bond.get('j')
        d = bond.get('distance_A')
        if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d is not None and isfinite(d) and d > 0 and occ[j] > 0:
            near[i] = min(near[i], d)
    weights = [0.0 for k in range(n)]
    first = [0.0 for k in range(n)]
    second = [0.0 for k in range(n)]
    for bond in bonds:
        i, j = bond.get('i'), bond.get('j')
        d = bond.get('distance_A')
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n:
            continue
        if d is None or not isfinite(d) or d <= 0 or d > 1.5 * near[i] or occ[j] <= 0:
            continue
        w = occ[j] * exp(-((d / (1.2 * near[i])) ** 6))
        weights[i] += w
        first[i] += w * d
        second[i] += w * d * d
    total = 0.0
    z = 0.0
    for i in range(n):
        if weights[i] > 0 and isfinite(occ[i]) and occ[i] > 0:
            mean = first[i] / weights[i]
            var = max(0.0, second[i] / weights[i] - mean * mean)
            if mean > 0:
                total += occ[i] * sqrt(var) / mean
                z += occ[i]
    return float(total / z) if z > 0 else nan

