def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        sites = s.get('sites') or []
        volume = (s.get('lattice') or {}).get('volume_A3')
        if volume is None or volume <= 0 or not sites:
            return 0.0
        v = volume / len(sites)
    return log(v)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    volume = (s.get('lattice') or {}).get('volume_A3')
    total = 0.0
    spheres = 0.0
    for site in sites:
        o = max(0.0, site.get('occupancy', 1.0) or 0.0)
        total += o
        r = (props.get(site.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            spheres += o * r ** 3
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        if v is None or v <= 0:
            return 0.0
        volume = v * total
    if volume <= 0:
        return 0.0
    return 4.0 * pi * spheres / (3.0 * volume)

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    composition = s.get('composition') or {}
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    electrons = 0.0
    covered = 0.0
    for element, fraction in composition.items():
        valence = (props.get(element) or {}).get('valence_electrons')
        if fraction is not None and fraction > 0 and valence is not None:
            electrons += fraction * max(0.0, valence)
            covered += fraction
    if covered <= 0:
        return 0.0
    return log1p(electrons / (covered * v))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    neighbors = s.get('neighbors') or []
    n = len(sites)
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    values = [0.0] * len(neighbors)
    count = 0
    for edge in neighbors:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
