    local = [(occ[i], sum(w for center, w in weighted if center == i)) for i in range(n) if occ[i] > 0 and radii[i] is not None and radii[i] > 0]
    total = sum(o for o, c in local)
    if total <= 0:
        return 0.0
    mean = sum(o * c for o, c in local) / total
    if mean <= 1e-12:
        return 0.0
    variance = sum(o * (c - mean) ** 2 for o, c in local) / total
    return max(0.0, variance / (mean * mean))
